const item = $input.first().json || {};
const execution = item.execution || {};
const workflow = item.workflow || {};
const error = execution.error || {};
const node = error.node || {};

const workflowId = workflow.id ? String(workflow.id) : 'unknown';
const workflowName = workflow.name ? String(workflow.name).slice(0, 200) : null;
const nodeName = node.name ? String(node.name).slice(0, 200) : null;
const errorClass = error.name ? String(error.name).slice(0, 200) : 'WorkflowExecutionError';
const errorMessage = error.message ? String(error.message).slice(0, 500) : null;
const tenantId = (execution.customData && execution.customData.tenant_id) || $env.DEFAULT_TENANT_ID || '00000000-0000-0000-0000-000000000000';
const execId = execution.id || String(Date.now());

return [{
  json: {
    tenant_id: tenantId,
    idempotency_key: 'err-' + execId,
    body: {
      workflow_id: workflowId,
      workflow_name: workflowName,
      node_name: nodeName,
      error_class: errorClass,
      error_message: errorMessage
    }
  }
}];
